/* ============================================================
   CATALOGO PIATTI — pasta, minestre, zuppe, piatti freddi
   ------------------------------------------------------------
   Ogni piatto usa SOLO ingredienti presenti in FOODS (più i 4 NUOVI_ALIMENTI qui sotto),
   così calorie, macro, prezzi, lista della spesa, allergie ed esclusioni continuano a funzionare.

   Campi di un piatto:
   - id, nome
   - gruppo: "pasta" | "pasta_fredda" | "minestra" | "riso"
   - temp:   "caldo" | "freddo"
   - mesi:   mesi (1-12) in cui il piatto può comparire (stagionalità)
   - copre:  quali slot del pasto sostituisce ("proteina", "carbo", "verdura");
             gli slot NON coperti vengono riempiti dalla logica già esistente
             (es. "Pasta al pomodoro" copre carbo+verdura e a fianco resta la proteina)
   - ingredienti: [{ id, qty }] — quantità base in grammi (peso cotto, come nel database),
                  poi l'app le scala per centrare le calorie del pasto
   - aromi:  erbe/spezie non conteggiate (basilico, aglio, pepe...)
   - passi:  ricetta in pochi passaggi
   ============================================================ */

// Helper per i mesi: rangeMesi(10, 3) = ottobre..marzo (gestisce il passaggio d'anno)
const rangeMesi = (da, a) => {
  const out = [];
  for (let m = da; ; m = (m % 12) + 1) {
    out.push(m);
    if (m === a) break;
  }
  return out;
};
const TUTTO_ANNO = rangeMesi(1, 12);

// Helper per scrivere i piatti in forma compatta: "pasta:180,pomodori:150,olio_oliva:8"
const parseIng = (s) => s.split(",").map((x) => { const [id, qty] = x.split(":"); return { id, qty: Number(qty) }; });
const mkDish = (id, nome, gruppo, temp, m, copre, ingredienti, aromi, passi) => ({
  id, nome, gruppo, temp, mesi: m, copre, ingredienti: parseIng(ingredienti), aromi, passi,
});

