// Ingredienti "di contorno" che si possono togliere dal piatto se esclusi (es. niente latticini -> niente parmigiano);
// se è escluso un ingrediente qualsiasi, invece, il piatto non viene proposto.
const DROPPABLE_DISH_INGREDIENTS = ["parmigiano"];

// Mese (1-12) del giorno idx del ciclo, a partire dalla data di generazione: serve per la stagionalità dei piatti
function monthForDay(startDate, dayIdx) {
  const base = startDate ? new Date(startDate) : new Date();
  return new Date(base.getTime() + dayIdx * 86400000).getMonth() + 1;
}

// Ingredienti utilizzabili di un piatto rispetto alle esclusioni; null se il piatto non è proponibile
function usableDishIngredients(dish, excluded) {
  const out = [];
  for (const ingr of dish.ingredienti) {
    if (excluded.includes(ingr.id)) {
      if (DROPPABLE_DISH_INGREDIENTS.includes(ingr.id)) continue;
      return null;
    }
    out.push(ingr);
  }
  return out;
}

function dishHasFish(dish) {
  return dish.ingredienti.some((ingr) => {
    const food = FOODS.find((f) => f.id === ingr.id);
    return food && isFishFood(food);
  });
}

// Sceglie un piatto adatto a mese, esclusioni e schema del pesce. Restituisce null se nessun piatto è proponibile.
// - nel pasto del pesce fisso: solo piatti di pesce, oppure primi senza proteina (il pesce si aggiunge a parte)
// - nell'altro pasto principale di quel giorno: mai piatti di pesce
function pickDish({ dishMeal, forcedFishMeal, excluded, month, usedDishIds = [], lastGroup = null }) {
  let pool = PIATTI.filter((d) => d.mesi.includes(month) && !usedDishIds.includes(d.id) && usableDishIngredients(d, excluded));
  if (forcedFishMeal) {
    if (dishMeal === forcedFishMeal) pool = pool.filter((d) => dishHasFish(d) || !d.copre.includes("proteina"));
    else pool = pool.filter((d) => !dishHasFish(d));
  }
  if (pool.length === 0) return null;
  const varied = pool.filter((d) => d.gruppo !== lastGroup); // evita due piatti dello stesso tipo di fila
  const source = varied.length > 0 ? varied : pool;
  const chosen = source[Math.floor(Math.random() * source.length)];
  return { ...chosen, ingredienti: usableDishIngredients(chosen, excluded) };
}

// Prezzo "medio" di un alimento (tra le 3 fasce), usato per stimarne il costo relativo
function avgPrice(food) {
  return (food.price.discount + food.price.standard + food.price.premium) / 3;
}

// Sceglie un alimento a caso da una categoria, dando più probabilità a quelli economici
// se il budget giornaliero è basso, e più probabilità a quelli costosi se il budget è alto.
// budgetLevel va da 0 (budget minimo) a 1 (budget alto/illimitato).
// recentlyUsed = alimenti già usati nei giorni precedenti (per evitare ripetizioni troppo vicine nella settimana)
// allowedIds = se fornito, restringe la scelta solo a questi id (usato per colazione/spuntini, dove non tutti gli
// alimenti della categoria hanno senso — es. niente pasta a colazione)
function isFishFood(food) {
  return food.tags.includes("pesce");
}

// Abbinamenti "sensati" carbo/verdura in base al tipo di proteina scelta per pranzo/cena
// (es. pesce -> riso/patate/verdure leggere, carne rossa -> patate/polenta/verdure saporite).
// Sono preferenze morbide: se non c'è disponibilità (esclusioni, allergie...) si torna alla scelta libera.
function getProteinGroup(food) {
  if (!food) return null;
  if (food.tags.includes("pesce")) return "pesce";
  if (food.tags.includes("carne rossa")) return "carne_rossa";
  if (food.tags.includes("carne bianca")) return "carne_bianca";
  return null; // legumi, uova, tempeh: nessuna restrizione, si abbinano bene con tutto
}

const PAIRING_CARBO = {
  pesce: ["riso", "riso_basmati", "patate", "cous_cous", "quinoa", "farro", "pane_integrale"],
  carne_rossa: ["patate", "patate_dolci", "polenta", "riso_integrale", "farro", "pane_di_segale_integrale"],
  carne_bianca: ["riso", "riso_basmati", "cous_cous", "quinoa", "patate", "pasta_integrale", "pasta"],
};

const PAIRING_VERDURA = {
  pesce: ["zucchine", "pomodori", "finocchi", "rucola", "insalata_mista", "asparagi", "spinaci", "cetrioli", "carote"],
  carne_rossa: ["funghi", "cipolle", "peperoni", "melanzane", "cavolo", "radicchio", "carote", "broccoli"],
  carne_bianca: ["zucchine", "broccoli", "carote", "insalata_mista", "peperoni", "asparagi", "spinaci", "cavolfiore"],
};

// Raggruppamento più fine per le proteine, usato per proporre alternative dello stesso tipo
// quando si cambia un alimento (es. carne con carne, pesce con pesce, legumi con legumi)
function getFoodSubGroup(food) {
  if (food.cat !== "proteina") return food.cat;
  if (food.tags.includes("pesce")) return "pesce";
  if (food.tags.includes("legumi") || food.tags.includes("soia")) return "legumi";
  if (food.id === "uova") return "uova";
  return "carne"; // carne bianca, carne rossa, salumi
}

