function ResultView({ result, budget, onBack }) {
  // rootId identifica questa "dieta madre": resta fisso per tutta la vita di questo ResultView,
  // anche quando il check-in ogni 14 giorni aggiorna cycleResult.generatedAt. Serve per capire se
  // la sessione salvata in locale appartiene a questa dieta o è di una dieta precedente/diversa.
  const rootId = result.generatedAt;
  const SESSION_STORAGE_KEY = "dietplanner_session_v1";
  const loadSavedSession = () => {
    try {
      const raw = localStorage.getItem(SESSION_STORAGE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed.rootId === rootId ? parsed : null;
    } catch {
      return null;
    }
  };
  const savedSession = loadSavedSession();

  const [cycleResult, setCycleResult] = useState(savedSession?.cycleResult ?? result); // dati della dieta corrente: si aggiornano solo con il check-in ogni 14 giorni
  const { bmr, tdee, targets, costs, bodyFatPercent, leanMass, hydration, workoutTips, peso, excludedIds, generatedAt, formSnapshot } = cycleResult;
  const [weekPlan, setWeekPlan] = useState(savedSession?.weekPlan ?? cycleResult.weekPlan);
  const cheapestTier = Object.entries(costs).sort((a, b) => a[1] - b[1])[0][0];
  const fitsTier = Object.entries(costs).find(([, cost]) => cost <= budget);
  const [selectedDay, setSelectedDay] = useState(savedSession?.selectedDay ?? 0);
  const activeDay = weekPlan.days[selectedDay];
  const [editingItem, setEditingItem] = useState(null); // { dayIdx, itemIdx } o null
  const [openRecipe, setOpenRecipe] = useState(null); // { dayIdx, pasto } o null
  const [showShoppingList, setShowShoppingList] = useState(true);
  const [checkedItems, setCheckedItems] = useState(savedSession?.checkedItems ?? {}); // { foodId: true/false }
  const [activeTab, setActiveTab] = useState(savedSession?.activeTab ?? "dieta"); // "dieta" | "spesa" | "passi"
  const [stepsLog, setStepsLog] = useState(savedSession?.stepsLog ?? {}); // { "2026-06-20": 8000, ... } inserimento manuale
  // Mascotte: una volta scelta (mascotData.chosen = true) non si può più cambiare
  const [mascotData, setMascotData] = useState(savedSession?.mascotData ?? {
    chosen: false,
    name: "",
  });
  // Streak: giorni consecutivi di apertura dell'app
  const [streakLog] = useState(() => openStreak(savedSession?.streakLog ?? null));
  // Frase della mascotte: una nuova ad ogni apertura dell'app, adatta all'ora del giorno
  const [mascotPhrase] = useState(() => pickMascotPhrase());

  // Salva la sessione ad ogni modifica, così sopravvive al ricaricamento della pagina
  useEffect(() => {
    try {
      localStorage.setItem(
        SESSION_STORAGE_KEY,
        JSON.stringify({ rootId, cycleResult, weekPlan, selectedDay, checkedItems, activeTab, stepsLog, mascotData, streakLog })
      );
    } catch {
      // Se il salvataggio fallisce l'app continua a funzionare, semplicemente non ricorda tra una sessione e l'altra
    }
  }, [rootId, cycleResult, weekPlan, selectedDay, checkedItems, activeTab, stepsLog, mascotData, streakLog]);

  // Ogni 14 giorni la dieta va rinnovata: chiediamo di nuovo peso/circonferenze/allenamento/obiettivo
  // e ricalcoliamo SOLO la dieta. Mascotte, streak e passi restano invariati.
  const daysInCycle = Math.floor((Date.now() - generatedAt) / 86400000);
  const cycleDue = daysInCycle >= 14;

  const handleCheckIn = (updatedFields) => {
    const newForm = { ...formSnapshot, ...updatedFields };
    const computed = computeDietResult(newForm, excludedIds);
    setCycleResult({ ...computed, excludedIds, generatedAt: Date.now(), formSnapshot: newForm });
    setWeekPlan(computed.weekPlan);
    setSelectedDay(0);
    setCheckedItems({});
    setEditingItem(null);
    setOpenRecipe(null);
    setActiveTab("dieta");
  };

  const toggleChecked = (foodId) =>
    setCheckedItems((prev) => ({ ...prev, [foodId]: !prev[foodId] }));

  // Rigenera da capo un solo giorno (nuovi alimenti pescati a caso), mantenendo invariati gli altri 13.
  // Rispetta le stesse esclusioni/budget della dieta originale e lo schema fisso del pesce.
  const regenerateDay = (dayIdx) => {
    const budgetLevel = budgetToLevel(budget);
    const forcedFishMeal = FISH_SCHEDULE_BY_WEEKDAY_IDX[dayIdx % 7] || null;
    const dishMeal = DISH_PLAN[dayIdx] || null;
    setWeekPlan((prev) => {
      // Alimenti usati nei giorni vicini (prima e dopo), per non ripetere troppo simile a quelli attorno
      const recentlyUsed = prev.days
        .filter((_, i) => i !== dayIdx && Math.abs(i - dayIdx) <= 3)
        .flatMap((d) => d.plan.items.map((it) => it.food.id));
      const usedDishIds = prev.days.filter((_, i) => i !== dayIdx).map((d) => d.plan.piattoId).filter(Boolean);
      const dish = dishMeal
        ? pickDish({ dishMeal, forcedFishMeal, excluded: excludedIds, month: monthForDay(prev.startDate, dayIdx), usedDishIds })
        : null;
      const newDayPlan = buildDayPlan(excludedIds, targets.kcalTarget, budgetLevel, recentlyUsed, forcedFishMeal, dishMeal, dish);
      const days = [...prev.days];
      days[dayIdx] = { ...days[dayIdx], plan: newDayPlan };
      return { ...prev, days };
    });
    setEditingItem(null);
    setOpenRecipe(null);
  };

  // Cambia solo il piatto di un pasto (pranzo o cena), lasciando invariato il resto della giornata.
  // Sceglie un altro piatto adatto a stagione, esclusioni e pesce fisso, non ancora usato nel ciclo.
  const swapDish = (dayIdx, pasto) => {
    setWeekPlan((prev) => {
      const day = prev.days[dayIdx];
      const currentId = day.plan.items.find((i) => i.pasto === pasto && i.piatto)?.piatto.id;
      if (!currentId) return prev;
      const forcedFishMeal = FISH_SCHEDULE_BY_WEEKDAY_IDX[dayIdx % 7] || null;
      const month = monthForDay(prev.startDate, dayIdx);
      const usedDishIds = prev.days.map((d) => d.plan.piattoId).filter(Boolean);
      const pickArgs = { dishMeal: pasto, forcedFishMeal, excluded: excludedIds, month };
      // prima cerca tra i piatti mai usati nel ciclo, poi (se sono finiti) ammette quelli già usati altrove
      const newDish =
        pickDish({ ...pickArgs, usedDishIds }) ?? pickDish({ ...pickArgs, usedDishIds: [currentId] });
      if (!newDish) return prev;

      const otherItems = day.plan.items.filter((i) => i.pasto !== pasto);
      const portions = buildMealPortions(pasto, {
        excluded: excludedIds,
        budgetLevel: budgetToLevel(budget),
        usedToday: otherItems.map((i) => i.food.id),
        recentlyUsed: [],
        forcedFishMeal,
        dishMeal: pasto,
        dish: newDish,
      });
      const newMealItems = finalizeItems(portions, targets.kcalTarget);
      const firstIdx = day.plan.items.findIndex((i) => i.pasto === pasto);
      const items = [
        ...day.plan.items.slice(0, firstIdx),
        ...newMealItems,
        ...day.plan.items.slice(firstIdx).filter((i) => i.pasto !== pasto),
      ];
      const days = [...prev.days];
      days[dayIdx] = { ...day, plan: { ...day.plan, items, totals: sumTotals(items), piattoId: newDish.id } };
      return { ...prev, days };
    });
    setEditingItem(null);
    setOpenRecipe(null);
  };

  // Sostituisce un alimento con un altro della stessa categoria, mantenendo i grammi/pezzi
  // e ricalcolando kcal/macro in base ai valori nutrizionali del nuovo alimento scelto
  const swapItem = (dayIdx, itemIdx, newFood) => {
    setWeekPlan((prev) => {
      const days = [...prev.days];
      const day = { ...days[dayIdx], plan: { ...days[dayIdx].plan } };
      const items = [...day.plan.items];
      const oldItem = items[itemIdx];
      const grams = newFood.perEgg ? oldItem.qty * 50 : newFood.perPiece ? oldItem.qty * 150 : oldItem.qty;
      const factor = grams / 100;
      items[itemIdx] = {
        food: newFood,
        qty: oldItem.qty,
        pasto: oldItem.pasto,
        kcal: newFood.kcal * factor,
        p: newFood.p * factor,
        c: newFood.c * factor,
        f: newFood.f * factor,
      };
      const totals = items.reduce(
        (acc, i) => ({ kcal: acc.kcal + i.kcal, p: acc.p + i.p, c: acc.c + i.c, f: acc.f + i.f }),
        { kcal: 0, p: 0, c: 0, f: 0 }
      );
      day.plan.items = items;
      day.plan.totals = totals;
      days[dayIdx] = day;
      return { ...prev, days };
    });
    setEditingItem(null);
  };

  const TABS = [
    { key: "dieta", label: "Dieta", icon: <Flame size={20} /> },
    { key: "spesa", label: "Spesa", icon: <Wallet size={20} /> },
    { key: "passi", label: "Passi", icon: <Activity size={20} /> },
    { key: "mascotte", label: "Mascotte", icon: <span style={{ fontSize: 18 }}>🏆</span> },
  ];

  // Ogni 14 giorni la dieta va rinnovata: schermata bloccante finché non si aggiornano i dati
  if (cycleDue) {
    return <CheckInScreen initialForm={formSnapshot} onSubmit={handleCheckIn} />;
  }

  return (
    <div style={{ paddingBottom: 90 }}>
      {activeTab === "dieta" && (
        <DietaTab
          bmr={bmr}
          tdee={tdee}
          targets={targets}
          bodyFatPercent={bodyFatPercent}
          leanMass={leanMass}
          hydration={hydration}
          workoutTips={workoutTips}
          weekPlan={weekPlan}
          selectedDay={selectedDay}
          setSelectedDay={setSelectedDay}
          activeDay={activeDay}
          editingItem={editingItem}
          setEditingItem={setEditingItem}
          openRecipe={openRecipe}
          setOpenRecipe={setOpenRecipe}
          swapItem={swapItem}
          swapDish={swapDish}
          regenerateDay={regenerateDay}
          onBack={onBack}
        />
      )}

      {activeTab === "spesa" && (
        <SpesaTab
          weekPlan={weekPlan}
          showShoppingList={showShoppingList}
          setShowShoppingList={setShowShoppingList}
          checkedItems={checkedItems}
          toggleChecked={toggleChecked}
          costs={costs}
          budget={budget}
          cheapestTier={cheapestTier}
          fitsTier={fitsTier}
        />
      )}

      {activeTab === "passi" && <PassiTab stepsLog={stepsLog} setStepsLog={setStepsLog} peso={peso} />}


      {activeTab === "mascotte" && (
        <MascotteTab
          mascotData={mascotData}
          setMascotData={setMascotData}
          streak={calcStreak(streakLog)}
          freezeAvailable={isFreezeAvailable(streakLog)}
          freezeUsedToday={streakLog.freezeUsedOn === todayStr()}
          phrase={mascotPhrase}
        />
      )}

      {/* Barra di navigazione in basso, stile app con tab fisse */}
      <div
        style={{
          position: "fixed",
          bottom: 0,
          left: 0,
          right: 0,
          background: "#FBF6EC",
          borderTop: "1px solid #C2A87F",
          display: "flex",
          justifyContent: "space-around",
          padding: "10px 0 calc(10px + env(safe-area-inset-bottom))",
          zIndex: 50,
        }}
      >
        {TABS.map((tab) => {
          const isActive = activeTab === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className="sans"
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 3,
                background: "none",
                border: "none",
                cursor: "pointer",
                color: isActive ? "#3E5C3A" : "#9A937F",
                fontSize: 11,
                fontWeight: isActive ? 700 : 500,
                padding: "4px 18px",
              }}
            >
              {tab.icon}
              {tab.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// --- TAB 1: Dieta — fabbisogno, timing allenamento, programma 14 giorni ---
function DietaTab({ bmr, tdee, targets, bodyFatPercent, leanMass, hydration, workoutTips, weekPlan, selectedDay, setSelectedDay, activeDay, editingItem, setEditingItem, openRecipe, setOpenRecipe, swapItem, swapDish, regenerateDay, onBack }) {
  return (
    <div style={{ display: "grid", gap: 22 }}>
      <div className="card">
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 4 }}>
          Il tuo fabbisogno
        </div>
        <div style={{ display: "flex", gap: 28, flexWrap: "wrap", marginTop: 10, rowGap: 18 }}>
          <Stat label="BMR (metabolismo basale)" value={`${Math.round(bmr)} kcal`} />
          <Stat label="TDEE (dispendio energetico totale)" value={`${Math.round(tdee)} kcal`} />
          <Stat label="Target giornaliero" value={`${Math.round(targets.kcalTarget)} kcal`} highlight />
        </div>
        <div className="sans" style={{ fontSize: 12.5, color: "#5B6651", marginTop: 14, padding: "10px 12px", background: "#F0EDE0", borderRadius: 8 }}>
          {bodyFatPercent != null ? (
            <span>Massa grassa stimata: <b>{bodyFatPercent.toFixed(1)}%</b> · Massa magra: <b>{leanMass.toFixed(1)} kg</b> — calcolata dalle tue misure (formula US Navy)</span>
          ) : (
            <span>Massa magra stimata: <b>{leanMass.toFixed(1)} kg</b> — nessuna misura inserita, uso una media generica. Inserisci collo/vita (e fianchi se donna) per un calcolo più preciso delle proteine.</span>
          )}
        </div>
        <div style={{ display: "flex", gap: 18, marginTop: 18, flexWrap: "wrap" }}>
          <Macro icon={<Beef size={15} />} label="Proteine" value={`${Math.round(targets.proteine_g)} g`} color="#9D4B3C" />
          <Macro icon={<Wheat size={15} />} label="Carboidrati" value={`${Math.round(targets.carbo_g)} g`} color="#B08A2E" />
          <Macro icon={<Droplet size={15} />} label="Grassi" value={`${Math.round(targets.grassi_g)} g`} color="#3E5C3A" />
          <Macro icon={<Droplet size={15} />} label="Acqua" value={`${(hydration.totalMl / 1000).toFixed(1)} L`} color="#2E6B8A" />
        </div>
        {hydration.extraMl > 0 && (
          <div className="sans" style={{ fontSize: 12, color: "#9A937F", marginTop: 8 }}>
            Di cui ~{(hydration.extraMl / 1000).toFixed(1)} L extra per compensare il sudore dell'attività sportiva.
          </div>
        )}
      </div>

      {workoutTips && (
        <div className="card">
          <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 14 }}>
            Cosa mangiare prima e dopo l'allenamento
          </div>
          <div style={{ display: "grid", gap: 14 }}>
            <div>
              <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4 }}>Prima — {workoutTips.pre.timing}</div>
              <div className="sans" style={{ fontSize: 13.5, color: "#5B6651" }}>{workoutTips.pre.suggerimento}</div>
            </div>
            <div>
              <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4 }}>Dopo — {workoutTips.post.timing}</div>
              <div className="sans" style={{ fontSize: 13.5, color: "#5B6651" }}>{workoutTips.post.suggerimento}</div>
            </div>
          </div>
        </div>
      )}

      <div className="card">
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 14 }}>
          Programma su ciclo di 14 giorni
        </div>

        {[0, 1].map((weekIdx) => (
          <div key={weekIdx} style={{ marginBottom: weekIdx === 0 ? 14 : 18 }}>
            <div className="sans" style={{ fontSize: 11, color: "#9A937F", marginBottom: 6, textTransform: "uppercase", letterSpacing: 0.5 }}>
              Settimana {weekIdx + 1}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6 }}>
              {weekPlan.days.slice(weekIdx * 7, weekIdx * 7 + 7).map((d, i) => {
                const idx = weekIdx * 7 + i;
                const dayNumber = idx + 1;
                const dayName = d.day.split(" (")[0].slice(0, 3);
                const isSelected = selectedDay === idx;
                return (
                  <button
                    key={idx}
                    onClick={() => setSelectedDay(idx)}
                    className="sans"
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      justifyContent: "center",
                      padding: "10px 4px",
                      borderRadius: 10,
                      border: isSelected ? "1.5px solid #3E5C3A" : "1.5px solid #C9B89A",
                      background: isSelected ? "#3E5C3A" : "#FBF6EC",
                      color: isSelected ? "#F7F4ED" : "#1F2A1E",
                      cursor: "pointer",
                      transition: "all .15s",
                    }}
                  >
                    <span style={{ fontSize: 10, opacity: 0.75, textTransform: "uppercase" }}>{dayName}</span>
                    <span style={{ fontSize: 16, fontWeight: 700 }}>{dayNumber}</span>
                  </button>
                );
              })}
            </div>
          </div>
        ))}

        <div className="sans" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 12, color: "#9A937F", marginBottom: 12, paddingTop: 4, borderTop: "1px solid #E5DFD0" }}>
          <span>{activeDay.day} — piano generato in base al tuo budget, diverso ogni giorno nel ciclo di 14 giorni</span>
          <button
            onClick={() => regenerateDay(selectedDay)}
            className="sans"
            style={{ fontSize: 11, color: "#3E5C3A", background: "none", border: "1px solid #3E5C3A", borderRadius: 6, padding: "3px 8px", cursor: "pointer", whiteSpace: "nowrap", marginLeft: 10 }}
          >
            🔄 Rigenera giorno
          </button>
        </div>

        <div style={{ display: "grid", gap: 22 }}>
          {[
            { key: "colazione", label: "Colazione" },
            { key: "spuntino_mattina", label: "Spuntino di metà mattina" },
            { key: "pranzo", label: "Pranzo" },
            { key: "spuntino_pomeriggio", label: "Spuntino del pomeriggio" },
            { key: "cena", label: "Cena" },
          ].map(({ key, label }) => {
            const mealItems = activeDay.plan.items.filter((i) => i.pasto === key);
            const mealKcal = mealItems.reduce((s, i) => s + i.kcal, 0);
            const mainItems = mealItems.filter((i) => i.food.cat !== "grasso");
            const condimenti = mealItems.filter((i) => i.food.cat === "grasso");
            const isRecipeOpen = openRecipe && openRecipe.dayIdx === selectedDay && openRecipe.pasto === key;
            const dishItem = mealItems.find((i) => i.piatto);
            const dish = dishItem ? PIATTI.find((d) => d.id === dishItem.piatto.id) : null;
            return (
              <div key={key}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 8 }}>
                  <div style={{ fontWeight: 600, fontSize: 16 }}>{label}</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div className="sans" style={{ fontSize: 12, color: "#9A937F" }}>{Math.round(mealKcal)} kcal</div>
                    {dish && (
                      <button
                        onClick={() => swapDish(selectedDay, key)}
                        className="sans"
                        style={{ fontSize: 11, color: "#3E5C3A", background: "none", border: "1px solid #3E5C3A", borderRadius: 6, padding: "3px 8px", cursor: "pointer" }}
                      >
                        🔄 Cambia piatto
                      </button>
                    )}
                    {mainItems.length > 0 && (key === "pranzo" || key === "cena") && (
                      <button
                        onClick={() => setOpenRecipe(isRecipeOpen ? null : { dayIdx: selectedDay, pasto: key })}
                        className="sans"
                        style={{ fontSize: 11, color: "#3E5C3A", background: "none", border: "1px solid #3E5C3A", borderRadius: 6, padding: "3px 8px", cursor: "pointer" }}
                      >
                        {isRecipeOpen ? "Chiudi" : "🍳 Ricetta"}
                      </button>
                    )}
                  </div>
                </div>
                {dish && (
                  <div style={{ fontWeight: 600, fontSize: 14, color: "#3E5C3A", marginBottom: 6 }}>
                    {dish.nome}{" "}
                    <span className="sans" style={{ fontSize: 11, color: "#9A937F", fontWeight: 400 }}>
                      · {dish.temp === "freddo" ? "servito freddo" : "servito caldo"}
                    </span>
                  </div>
                )}
                <div style={{ display: "grid", gap: 6 }}>
                  {mainItems.map((item) => {
                    const realIdx = activeDay.plan.items.indexOf(item);
                    const isEditing = editingItem && editingItem.dayIdx === selectedDay && editingItem.itemIdx === realIdx;
                    const alternatives = FOODS.filter((f) => getFoodSubGroup(f) === getFoodSubGroup(item.food) && f.id !== item.food.id);
                    return (
                      <div key={realIdx}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 14, padding: "6px 0", borderBottom: !isEditing ? "1px solid #EFE9DA" : "none" }}>
                          <span>{item.food.name} — {item.food.perEgg || item.food.perPiece ? `${item.qty} pz` : resaOf(item.food) > 1 ? `${item.qty} g (peso cotto, ≈ ${Math.round(rawGrams(item.food, item.qty) / 5) * 5} g a crudo)` : `${item.qty} g`}</span>
                          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                            <span className="sans" style={{ color: "#7A8A6E" }}>{Math.round(item.kcal)} kcal</span>
                            {!item.piatto && (
                              <button
                                onClick={() => setEditingItem(isEditing ? null : { dayIdx: selectedDay, itemIdx: realIdx })}
                                className="sans"
                                style={{ fontSize: 11, color: "#3E5C3A", background: "none", border: "1px solid #3E5C3A", borderRadius: 6, padding: "3px 8px", cursor: "pointer" }}
                              >
                                {isEditing ? "Annulla" : "Cambia"}
                              </button>
                            )}
                          </div>
                        </div>
                        {isEditing && (
                          <div style={{ padding: "8px 0 12px", borderBottom: "1px solid #EFE9DA", display: "flex", gap: 6, flexWrap: "wrap" }}>
                            {alternatives.map((alt) => (
                              <span
                                key={alt.id}
                                className="chip"
                                style={{ fontSize: 12 }}
                                onClick={() => swapItem(selectedDay, realIdx, alt)}
                              >
                                {alt.name}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
                {condimenti.length > 0 && (
                  <div className="sans" style={{ fontSize: 12.5, color: "#9A937F", marginTop: 8, fontStyle: "italic" }}>
                    Condito con {condimenti.map((c) => `${c.food.name.toLowerCase()} (${c.qty}g, ${Math.round(c.kcal)} kcal)`).join(" + ")} — già incluso nel totale del pasto, da usare per cucinare/condire, non da mangiare a parte.
                  </div>
                )}
                {isRecipeOpen && (
                  <div style={{ marginTop: 8, padding: "10px 12px", background: "#F5F2E8", borderRadius: 8 }}>
                    {(() => {
                      const restItems = dish ? mainItems.filter((i) => !i.piatto) : mainItems; // ingredienti fuori dal piatto
                      const cookedItems = restItems.filter((i) => !isRawOnly(i.food));
                      const rawItems = restItems.filter((i) => isRawOnly(i.food));
                      const proteinItem = restItems.find((i) => i.food.cat === "proteina");
                      const group = proteinItem ? getProteinGroup(proteinItem.food) : null;
                      const finishing = pickFinishing(group, selectedDay * 31 + (proteinItem ? proteinItem.food.id.split("").reduce((a, c) => a + c.charCodeAt(0), 0) : 0));
                      return (
                        <div className="sans" style={{ fontSize: 13, lineHeight: 1.7 }}>
                          {dish && (
                            <div>
                              <div style={{ fontWeight: 600 }}>{dish.nome}</div>
                              <ol style={{ margin: "4px 0 6px 18px", padding: 0 }}>
                                {dish.passi.map((passo, i) => (
                                  <li key={i}>{passo}</li>
                                ))}
                              </ol>
                              {dish.aromi && <div>Aromi (facoltativi, non incidono su kcal/macro): {dish.aromi}.</div>}
                            </div>
                          )}
                          {cookedItems.length > 0 && (
                            <div>{dish ? "Da preparare a parte" : "Cuoci insieme"}: {cookedItems.map((i) => `${i.food.name} (${cookingTipFor(i.food)})`).join(", ")}.</div>
                          )}
                          {rawItems.length > 0 && (
                            <div>Tieni a crudo, da aggiungere solo alla fine: {rawItems.map((i) => i.food.name.toLowerCase()).join(", ")}.</div>
                          )}
                          {!dish && <div>Per insaporire il piatto (facoltativo, non incide su kcal/macro): {finishing}.</div>}
                          {dish ? (
                            <div>Servi il piatto{restItems.length > 0 ? `, accompagnato da ${restItems.map((i) => i.food.name.toLowerCase()).join(" e ")}` : ""}.</div>
                          ) : (
                            <div>Servi tutto insieme nello stesso piatto{condimenti.length > 0 ? `, condito con ${condimenti.map((c) => c.food.name.toLowerCase()).join(" e ")}` : ""}.</div>
                          )}
                        </div>
                      );
                    })()}
                    <a
                      className="sans"
                      href={`https://www.google.com/search?q=${encodeURIComponent("site:giallozafferano.it light OR dietetica " + (dish ? dish.nome : mainItems.map((i) => i.food.name).join(" ")))}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{ display: "inline-block", marginTop: 8, fontSize: 12.5, color: "#3E5C3A", textDecoration: "underline" }}
                    >
                      Idee ricette con questi ingredienti su GialloZafferano
                    </a>
                  </div>
                )}
              </div>
            );
          })}
        </div>
        <div className="sans" style={{ marginTop: 18, paddingTop: 14, borderTop: "1px solid #E5DFD0", fontSize: 13, color: "#5B6651" }}>
          Totale giornata: {Math.round(activeDay.plan.totals.kcal)} kcal · P {Math.round(activeDay.plan.totals.p)}g · C {Math.round(activeDay.plan.totals.c)}g · G {Math.round(activeDay.plan.totals.f)}g
        </div>
      </div>

      <button className="btn-primary" style={{ justifySelf: "start", background: "transparent", color: "#3E5C3A", border: "1.5px solid #3E5C3A" }} onClick={onBack}>
        ← Modifica dati
      </button>
    </div>
  );
}

// --- TAB 2: Spesa — lista della spesa con checkbox + costi per fascia di negozio ---
function SpesaTab({ weekPlan, showShoppingList, setShowShoppingList, checkedItems, toggleChecked, costs, budget, cheapestTier, fitsTier }) {
  return (
    <div style={{ display: "grid", gap: 22 }}>
      <div className="card">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: showShoppingList ? 14 : 0 }}>
          <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E" }}>
            Lista della spesa (ciclo di 14 giorni)
          </div>
          <button
            className="sans"
            onClick={() => setShowShoppingList((v) => !v)}
            style={{ fontSize: 12, color: "#3E5C3A", background: "none", border: "1px solid #3E5C3A", borderRadius: 6, padding: "5px 10px", cursor: "pointer" }}
          >
            {showShoppingList ? "Nascondi" : "Mostra"}
          </button>
        </div>
        {showShoppingList && (() => {
          const shoppingList = buildShoppingList(weekPlan);
          return (
            <div style={{ display: "grid", gap: 18 }}>
              {Object.entries(FOOD_CATEGORIES).map(([catKey, catLabel]) => {
                const entries = shoppingList[catKey];
                if (!entries || entries.length === 0) return null;
                return (
                  <div key={catKey}>
                    <div className="sans" style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: 0.5, color: "#9A937F", marginBottom: 6 }}>
                      {catLabel}
                    </div>
                    <div style={{ display: "grid", gap: 5 }}>
                      {entries.map(({ food, qty }) => {
                        const isChecked = !!checkedItems[food.id];
                        return (
                          <div
                            key={food.id}
                            onClick={() => toggleChecked(food.id)}
                            style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14, cursor: "pointer", padding: "2px 0" }}
                          >
                            <div
                              style={{
                                width: 18,
                                height: 18,
                                borderRadius: 5,
                                border: "1.5px solid #3E5C3A",
                                background: isChecked ? "#3E5C3A" : "transparent",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                flexShrink: 0,
                                color: "#F7F4ED",
                                fontSize: 12,
                              }}
                            >
                              {isChecked ? "✓" : ""}
                            </div>
                            <span style={{ flex: 1, textDecoration: isChecked ? "line-through" : "none", color: isChecked ? "#9A937F" : "#1F2A1E" }}>
                              {food.name}
                            </span>
                            <span className="sans" style={{ color: "#7A8A6E" }}>
                              {food.perEgg || food.perPiece ? `${Math.round(qty)} pz` : `${(qty / 1000).toFixed(2)} kg`}
                            </span>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
              <div className="sans" style={{ fontSize: 12, color: "#9A937F", paddingTop: 8, borderTop: "1px solid #E5DFD0" }}>
                Quantità totali per tutto il ciclo di 14 giorni — utile per fare la spesa in una o due volte. Pasta, riso, cereali e legumi sono indicati a crudo (peso secco, come si compra).
              </div>
            </div>
          );
        })()}
      </div>

      <div className="card">
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 14 }}>
          <MapPin size={13} style={{ display: "inline", marginRight: 4, verticalAlign: -2 }} />
          Costo settimanale medio stimato per fascia di negozio (calcolato sul ciclo di 14 giorni)
        </div>
        <div style={{ display: "grid", gap: 10 }}>
          {Object.entries(costs).map(([tier, cost]) => (
            <div key={tier} style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ width: 10, height: 10, borderRadius: "50%", background: TIER_COLORS[tier], flexShrink: 0 }} />
              <div style={{ flex: 1 }} className="sans">{TIER_LABELS[tier]}</div>
              <div className="sans" style={{ fontWeight: 600 }}>€{cost.toFixed(2)}</div>
            </div>
          ))}
        </div>
        <div style={{ marginTop: 16, padding: 14, background: "#F0EDE0", borderRadius: 10 }} className="sans">
          {fitsTier ? (
            <span>Con un budget di €{budget}/sett. il tuo piano rientra nella fascia <b>{TIER_LABELS[fitsTier[0]]}</b> (~€{fitsTier[1].toFixed(2)}). La fascia più economica resta <b>{TIER_LABELS[cheapestTier]}</b>.</span>
          ) : (
            <span>Anche nella fascia più economica (<b>{TIER_LABELS[cheapestTier]}</b>, ~€{costs[cheapestTier].toFixed(2)}/sett.) il piano supera il tuo budget di €{budget}. Valuta di alzare leggermente il budget o ridurre alcune porzioni più costose (es. tonno, petto di pollo).</span>
          )}
        </div>
        <div className="sans" style={{ marginTop: 10, fontSize: 12, color: "#9A937F" }}>
          Nota: prezzi medi indicativi, non in tempo reale. Geolocalizzazione dei punti vendita reali non ancora disponibile in questo prototipo.
        </div>
      </div>
    </div>
  );
}

// --- TAB 3: Passi — inserimento manuale dei passi quotidiani (in attesa di integrazione con Google Health/Apple Health) ---
function PassiTab({ stepsLog, setStepsLog, peso }) {
  const todayKey = new Date().toISOString().slice(0, 10);
  const todaySteps = stepsLog[todayKey] || 0;
  const todayKcal = kcalFromSteps(todaySteps, peso);
  const [inputValue, setInputValue] = useState("");

  const saveSteps = () => {
    const val = parseInt(inputValue, 10);
    if (!Number.isNaN(val) && val >= 0) {
      setStepsLog((prev) => ({ ...prev, [todayKey]: val }));
      setInputValue("");
    }
  };

  const history = Object.entries(stepsLog)
    .sort((a, b) => (a[0] < b[0] ? 1 : -1))
    .slice(0, 14);

  return (
    <div style={{ display: "grid", gap: 22 }}>
      <div className="card">
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 4 }}>
          Contapassi (inserimento manuale)
        </div>
        <div className="sans" style={{ fontSize: 12.5, color: "#5B6651", marginTop: 6, marginBottom: 16 }}>
          Per ora i passi si inseriscono a mano. In futuro questa sezione potrà collegarsi automaticamente a Google Health o Apple Health, per leggere in automatico dal telefono passi, battito cardiaco, minuti attivi e tutto ciò che quei servizi già misurano.
        </div>

        <div style={{ display: "flex", gap: 28, flexWrap: "wrap", rowGap: 18 }}>
          <Stat label="Passi registrati oggi" value={todaySteps.toLocaleString("it-IT")} highlight />
          <Stat label="Kcal bruciate camminando" value={`${Math.round(todayKcal)} kcal`} />
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          <input
            className="field"
            type="number"
            placeholder="es. 8000"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            style={{ flex: 1 }}
          />
          <button className="btn-primary" onClick={saveSteps}>
            Salva
          </button>
        </div>
        {todaySteps > 0 && (
          <div className="sans" style={{ fontSize: 12, color: "#9A937F", marginTop: 8 }}>
            Salvando di nuovo per oggi, il valore di oggi viene sovrascritto (non somma). Stima kcal calcolata sul tuo peso attuale ({peso} kg).
          </div>
        )}
      </div>

      {history.length > 0 && (
        <div className="card">
          <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 14 }}>
            Storico recente
          </div>
          <div style={{ display: "grid", gap: 8 }}>
            {history.map(([date, steps]) => (
              <div key={date} style={{ display: "flex", justifyContent: "space-between", fontSize: 14, padding: "6px 0", borderBottom: "1px solid #EFE9DA" }}>
                <span className="sans">{date}</span>
                <span style={{ fontWeight: 600 }}>
                  {steps.toLocaleString("it-IT")} passi
                  <span className="sans" style={{ fontWeight: 400, color: "#9A937F", marginLeft: 8, fontSize: 13 }}>
                    ~{Math.round(kcalFromSteps(steps, peso))} kcal
                  </span>
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}


// --- TAB 4: Mascotte — la mela, con nome scelto una sola volta e streak ---
function MascotteTab({ mascotData, setMascotData, streak, freezeAvailable, freezeUsedToday, phrase }) {
  if (!mascotData.chosen) {
    return <MascotPicker setMascotData={setMascotData} />;
  }

  return (
    <div style={{ display: "grid", gap: 22 }}>
      <div className="card" style={{ textAlign: "center", maxWidth: 480, margin: "0 auto", width: "100%" }}>
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 14 }}>
          La tua mascotte
        </div>

        {phrase && (
          // Fumetto: la codina (quadrato ruotato) punta verso la mela
          <div style={{ position: "relative", margin: "0 auto 18px", maxWidth: 330, padding: "12px 16px", background: "#FFFDF7", border: "1.5px solid #C2A87F", borderRadius: 20, fontSize: 15, lineHeight: 1.4, boxShadow: "0 2px 6px rgba(80, 60, 30, 0.10)" }}>
            {phrase.testo}
            <div
              style={{ position: "absolute", left: "50%", bottom: -9, width: 16, height: 16, marginLeft: -8, background: "#FFFDF7", borderRight: "1.5px solid #C2A87F", borderBottom: "1.5px solid #C2A87F", transform: "rotate(45deg)" }}
            />
          </div>
        )}

        <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}>
          <img src={IMG_MELA_FELICE} alt={mascotData.name} style={{ width: "100%", maxWidth: 400, height: "auto" }} />
        </div>

        <div style={{ fontSize: 22, fontWeight: 700 }}>{mascotData.name || "Senza nome"}</div>

        <div style={{ marginTop: 18, paddingTop: 14, borderTop: "1px solid #E5DFD0" }}>
          <div className="sans" style={{ fontSize: 12, color: "#9A937F" }}>Streak attuale</div>
          <div style={{ fontSize: 26, fontWeight: 700, color: "#3E5C3A" }}>🔥 {streak} {streak === 1 ? "giorno" : "giorni"}</div>
          <div className="sans" style={{ fontSize: 13, marginTop: 8, color: freezeAvailable ? "#3E7CB1" : "#9A937F" }}>
            ❄️ Streak freeze: {freezeAvailable ? "disponibile questo mese" : "già usato questo mese"}
          </div>
          {freezeUsedToday && (
            <div className="sans" style={{ fontSize: 12, marginTop: 4, color: "#3E7CB1" }}>
              Hai saltato un giorno: il freeze ha salvato la tua streak!
            </div>
          )}
          <div className="sans" style={{ fontSize: 11.5, marginTop: 6, color: "#9A937F" }}>
            Il freeze salva la streak se salti un solo giorno, una volta al mese.
          </div>
        </div>
      </div>
    </div>
  );
}

// Schermata di scelta iniziale della mascotte (nome, scelta definitiva)
function MascotPicker({ setMascotData }) {
  const [name, setName] = useState("");
  const [confirming, setConfirming] = useState(false);

  const canConfirm = name.trim();

  const confirm = () => {
    setMascotData({ chosen: true, name: name.trim() });
  };

  return (
    <div style={{ display: "grid", gap: 22 }}>
      <div className="card" style={{ maxWidth: 600, margin: "0 auto", width: "100%" }}>
        <div className="sans" style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: 1, color: "#7A8A6E", marginBottom: 6 }}>
          La tua mascotte
        </div>
        <div className="sans" style={{ fontSize: 12.5, color: "#5B6651", marginBottom: 16 }}>
          Il nome è <b>definitivo</b>, non potrai cambiarlo in seguito.
        </div>

        <div style={{ display: "flex", justifyContent: "center", marginBottom: 16 }}>
          <img src={IMG_MELA_FELICE} alt="Mascotte" style={{ width: "100%", maxWidth: 300, height: "auto" }} />
        </div>

        <div style={{ display: "grid", gap: 14 }}>
          <Field label="Dai un nome alla tua mascotte">
            <input className="field" type="text" value={name} onChange={(e) => setName(e.target.value)} />
          </Field>
        </div>

        {!confirming ? (
          <button
            className="btn-primary"
            style={{ marginTop: 18, opacity: canConfirm ? 1 : 0.5, cursor: canConfirm ? "pointer" : "default" }}
            disabled={!canConfirm}
            onClick={() => canConfirm && setConfirming(true)}
          >
            Conferma
          </button>
        ) : (
          <div style={{ marginTop: 18, padding: 14, background: "#F5E6E0", borderRadius: 10 }}>
            <div className="sans" style={{ fontSize: 13, color: "#9D4B3C", marginBottom: 10 }}>
              Sei sicuro? Il nome non si potrà cambiare in seguito.
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <button className="btn-primary" onClick={confirm}>Confermo, è definitivo</button>
              <button
                className="sans"
                onClick={() => setConfirming(false)}
                style={{ background: "transparent", border: "1px solid #9D4B3C", color: "#9D4B3C", borderRadius: 8, padding: "10px 16px", cursor: "pointer" }}
              >
                Annulla
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}


function Stat({ label, value, highlight }) {
  return (
    <div style={{ minWidth: 140 }}>
      <div className="sans" style={{ fontSize: 11, color: "#9A937F" }}>{label}</div>
      <div style={{ fontSize: highlight ? 26 : 20, fontWeight: 700, color: highlight ? "#3E5C3A" : "#1F2A1E" }}>{value}</div>
    </div>
  );
}

function Macro({ icon, label, value, color }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <div style={{ color }}>{icon}</div>
      <div>
        <div className="sans" style={{ fontSize: 11, color: "#9A937F" }}>{label}</div>
        <div style={{ fontWeight: 600, fontSize: 15 }}>{value}</div>
      </div>
    </div>
  );
}

